select n.id as id from notes n  left join (select rank_view.entity_id as note_id, count(*) as metric from analytics_events rank_view where rank_view.event_type = 'PUBLIC_NOTE_VIEWED' and rank_view.entity_id is not null group by rank_view.entity_id) rank_views on rank_views.note_id = n.id  where n.visibility = 'PUBLIC' order by coalesce(rank_views.metric, 0) desc, n.created_at desc, n.id asc fetch first ? rows only